const features={dashboard:{label:'PRIORITY FIRST',title:'先处理需要你决策的事。',copy:'用未完成任务、待审批、风险和新品四个维度建立全局概览，再把审批队列与阻塞项放进工作入口。',heading:'驾驶舱 · 优先级组织',rows:[['审批队列','人工确认'],['风险与阻塞','及时接管'],['今日任务','明确下一步'],['业务入口','进入上下文']]},tasks:{label:'ONE TASK, MULTIPLE VIEWS',title:'同一批任务，不同观察方式。',copy:'列表用于查找，看板用于观察状态，时间轴用于理解截止时间。通过筛选与保存视图，聚焦当前需要推进的工作。',heading:'任务工作区 · 状态示意',rows:[['待开始 → 进行中','执行中'],['待审核 → 完成','审阅节点'],['阻塞','等待接管'],['摘要 / 文件 / 关联对象','详情侧栏']]},content:{label:'FROM INSPIRATION TO OBJECT',title:'保留来源，也保留演变。',copy:'内容灵感记录来源、标签和可复用元素；模型对象记录阶段、版本与工艺风险，让灵感与研发过程有据可查。',heading:'内容与模型 · 对象结构',rows:[['灵感来源 / 平台 / 作者','内容依据'],['选题预览 → 人工审批','制作入口'],['姿态 / 穿搭 / 模型版本','研发上下文'],['四视图 / 灰模 / 涂装','阶段追踪']]},orders:{label:'HUMAN IN THE LOOP',title:'关键状态，需要清楚的确认。',copy:'以订单状态组织生产与交付。原型对关键变更提供确认预览，并设计审计信息，记录操作依据与修改前后值。',heading:'订单与审计 · 关键控制',rows:[['付款 / 地址 / 可发货','人工复核'],['修改前值 → 修改后值','变更依据'],['操作者 / 来源 / 置信度','审计字段'],['云端保存 / 审批 / 上传','当前未开放']]}};
const tabs=[...document.querySelectorAll('[data-feature]')];function select(key){const f=features[key];tabs.forEach(b=>{const on=b.dataset.feature===key;b.setAttribute('aria-selected',String(on));b.tabIndex=on?0:-1});const panel=document.querySelector('#feature');panel.setAttribute('aria-labelledby','tab-'+key);panel.innerHTML=`<div><small>${f.label}</small><h3>${f.title}</h3><p>${f.copy}</p></div><div class="feature-visual"><h4>${f.heading}</h4>${f.rows.map(r=>`<div class="visual-row"><span>${r[0]}</span><span>${r[1]}</span></div>`).join('')}<p class="visual-caption">依据原站功能结构整理 · 非实时业务界面</p></div>`}tabs.forEach((b,i)=>{b.addEventListener('click',()=>select(b.dataset.feature));b.addEventListener('keydown',e=>{let n;if(e.key==='ArrowRight')n=(i+1)%tabs.length;if(e.key==='ArrowLeft')n=(i+tabs.length-1)%tabs.length;if(e.key==='Home')n=0;if(e.key==='End')n=tabs.length-1;if(n!==undefined){e.preventDefault();tabs[n].focus();select(tabs[n].dataset.feature)}})});select('dashboard');

const preview=document.querySelector(".preview-viewport");if(preview){new ResizeObserver(()=>{preview.style.setProperty("--preview-scale",preview.clientWidth/1440)}).observe(preview)}
